#!/usr/bin/env python3
"""Strict frozen gate for the guarded R3 roll DeePC design pilot."""
import argparse,csv,json,math,sys
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path[:0]=[str(ROOT),str(ROOT/'scripts')]
from deepc.src.r3_roll_runtime import R3RollDeePCRuntime
from design_rich_r3_roll_lqr_disturbance import disturbance
from run_rich_r3_roll_dualrate_xp12 import start_reasons

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('csv',type=Path);p.add_argument('--require-engaged',action='store_true');a=p.parse_args();cfg=json.loads((ROOT/'deepc/configs/rich_R3_deepc_pilot.json').read_text());g=cfg['pilot_gates'];lim=cfg['limits']
 with a.csv.open(newline='') as f:rows=list(csv.DictReader(f))
 if len(rows)<2:raise SystemExit('insufficient rows')
 t=np.array([float(r['t_s']) for r in rows]);dt=np.diff(t);command=np.array([float(r['deepc_command']) for r in rows]);sent=np.array([float(r['sent_roll_perturbation']) for r in rows]);runtime_ms=np.array([float(r['runtime_ms']) for r in rows]);p_error=np.array([float(r['p_error_deg_s']) for r in rows]);latched=np.array([int(r['fallback_latched']) for r in rows],bool);updates=np.array([int(r['fallback_update']) for r in rows],bool);rt=R3RollDeePCRuntime();replay=history_error=0.
 for r in rows:
  preu=np.array([float(r[f'pre_u_history_{i}']) for i in range(5)]);prep=np.array([float(r[f'pre_p_history_{i}']) for i in range(5)]);history_error=max(history_error,float(np.max(abs(preu-rt.u_history))),float(np.max(abs(prep-rt.p_history))));expected=rt.update(float(r['p_error_deg_s']));replay=max(replay,abs(expected['command']-float(r['deepc_command'])));postu=np.array([float(r[f'post_u_history_{i}']) for i in range(5)]);postp=np.array([float(r[f'post_p_history_{i}']) for i in range(5)]);history_error=max(history_error,float(np.max(abs(postu-rt.u_history))),float(np.max(abs(postp-rt.p_history))))
 first={k:float(rows[0][k]) for k in ('altitude_m','ias_kts','pitch_deg','roll_deg','p_deg_s','q_deg_s','r_deg_s','art_stab_on','override_roll','override_pitch','paused','sim_speed','replay')};reasons=start_reasons(first);engaged=all(r['engaged']=='1' and r['controls_sent']=='1' for r in rows);active=(t>=10)&(t<18);final=t>=25;realized=np.array([float(r['yoke_roll_ratio'])-float(r['yoke_roll_bias']) for r in rows]);corr=float(np.corrcoef(sent[:-1],realized[1:])[0,1]);restoration=max(abs(float(rows[-1][k])) for k in ('restored_roll_yoke_error','restored_pitch_yoke_error'));logged_disturbance=np.array([float(r['disturbance_command']) for r in rows]);expected_disturbance=np.array([disturbance(x) for x in t]);selection_error=float(np.max(abs(sent-(command+logged_disturbance))))
 checks={'completeness':len(rows)>=g['minimum_rows'],'maximum_gap':float(dt.max())<=g['maximum_gap_s'],'mean_rate':g['minimum_rate_hz']<=1/float(dt.mean())<=g['maximum_rate_hz'],'fallback_updates':297<=int(updates.sum())<=303,'start_gate':not reasons,'engagement':engaged if a.require_engaged else not engaged,'no_fallback_latch':not latched[-1],'permanent_latch':bool(np.all(np.diff(latched.astype(int))>=0)),'optimizer_convergence':all(r['deepc_converged']=='1' and r['deepc_fallback_required']=='0' for r in rows),'runtime_deadline':float(runtime_ms.max())<g['maximum_runtime_ms'],'exact_replay':replay<=1e-15,'exact_history':history_error<=1e-15,'disturbance_waveform':float(np.max(abs(logged_disturbance-expected_disturbance)))<=1e-15,'selection_exact':selection_error<=1e-15,'command_bound':float(np.max(abs(sent)))<=lim['command']+1e-15,'slew_bound':float(np.max(abs(np.diff(sent))))<=lim['slew_per_sample']+1e-15,'realized_input':corr>=g['minimum_sent_to_realized_lag1_correlation'] if a.require_engaged else True,'measurable_response':float(np.max(abs(p_error[active])))>=g['minimum_peak_abs_delta_p_deg_s'] if a.require_engaged else True,'rate_recovery':float(np.max(abs(p_error[final])))<=g['maximum_final_5s_abs_delta_p_deg_s'] if a.require_engaged else True,'ownership_restored':rows[-1]['restored_roll_override']=='0' and rows[-1]['restored_pitch_override']=='0' and restoration<=g['maximum_restoration_error'],'live_safety':all(float(r['paused'])==0 and float(r['sim_speed'])==1 and float(r['replay'])==0 and abs(float(r['pitch_deg']))<=lim['pitch_deg'] and abs(float(r['roll_deg']))<=lim['roll_deg'] and max(abs(float(r[k])) for k in ('p_deg_s','q_deg_s','r_deg_s'))<=lim['body_rate_deg_s'] for r in rows),'finite':all(math.isfinite(float(r[k])) for r in rows for k in ('runtime_ms','deepc_command','sent_roll_perturbation','p_error_deg_s'))};checks={k:bool(v) for k,v in checks.items()}
 result={'file':str(a.csv),'rows':len(rows),'effective_hz':1/float(dt.mean()),'maximum_gap_s':float(dt.max()),'runtime_ms':{'median':float(np.median(runtime_ms)),'p95':float(np.percentile(runtime_ms,95)),'max':float(runtime_ms.max())},'peak_abs_delta_p_deg_s':float(np.max(abs(p_error[active]))),'final_5s_max_abs_delta_p_deg_s':float(np.max(abs(p_error[final]))),'sent_to_realized_lag1_correlation':corr,'peak_abs_sent_perturbation':float(np.max(abs(sent))),'maximum_sent_slew':float(np.max(abs(np.diff(sent)))),'maximum_replay_error':replay,'maximum_history_error':history_error,'maximum_selection_error':selection_error,'fallback_reason':rows[-1]['fallback_reason'],'start_gate_reasons':reasons,'checks':checks,'pass':all(checks.values()),'claim_boundary':'Guarded DeePC design-pilot gate only.'};print(json.dumps(result,indent=2));raise SystemExit(0 if result['pass'] else 1)
if __name__=='__main__':main()
